package org.happyrun.app.remote.runtime;
import org.junit.Test;import static org.junit.Assert.*;
import java.nio.file.*;import java.time.*;import java.util.*;
import org.happyrun.app.remote.protocol.*;import org.happyrun.app.remote.transport.*;import org.happyrun.app.remote.journal.*;import org.happyrun.app.remote.simulation.*;
public class RemoteForegroundSessionTest {
 static final String A=RemoteAgentRunnerTest.AGENT,D=RemoteAgentRunnerTest.DEVICE,S=RemoteAgentRunnerTest.SESSION;
 static class Clock implements RemoteClock {
  double now;Runnable onSleep;public double monotonicSeconds(){return now;}public Instant utcNow(){return Instant.parse("2026-10-19T00:00:00Z").plusMillis((long)(now*1000));}public void sleepMillis(long ms){now+=ms/1000.;if(onSleep!=null)onSleep.run();}
 }
 static class Server implements AgentClient {
  final Clock c;final List<Double> claims=new ArrayList<>(),heartbeats=new ArrayList<>();int helloCount,completed,remaining,closeCount;boolean closed,ambiguous,unauthorized,unknownProfile,heartbeatFailure,renewFailure;JobView v;long fence;
  Server(Clock c,int count){this.c=c;remaining=count;}
  void open(){if(closed)throw new ControlException("client_closed",0,false,false);}
  public HelloResult hello(AgentHello h){open();helloCount++;if(unauthorized)throw new ControlException("http_rejected",401,false,false);return new HelloResult(A,10,30);}
  public Instant heartbeat(AgentHello h){open();heartbeats.add(c.now);if(heartbeatFailure)throw new ControlException("transport_failed",0,true,true);return c.utcNow();}
  public LeaseGrant claim(String d){open();claims.add(c.now);if(ambiguous)throw new ControlException("transport_failed",0,true,true);if(remaining--<=0)return null;fence++;String id=String.format("55555555-5555-4555-8555-%012d",fence);JobSpec spec=new JobSpec(1,"simulation",BundledSimulationProfiles.PROFILE_ID,unknownProfile?"0".repeat(64):BundledSimulationProfiles.PROFILE_REVISION,BundledSimulationProfiles.ROUTE_ID,BundledSimulationProfiles.ROUTE_REVISION,D,c.utcNow(),c.utcNow().plusSeconds(120),null);v=new JobView(id,spec,"leased",1,"run",fence,A,null,null,null,S);return new LeaseGrant(v,"test-lease",fence,c.utcNow().plusSeconds(30));}
  public JobView getJob(String id){open();return v;}
  public RenewResult renew(String id,LeaseCommand l){open();assertEquals(v.fence,l.fence);if(renewFailure)throw new ControlException("transport_failed",0,true,true);return new RenewResult(c.utcNow().plusSeconds(30),"run");}
  public JobView events(String id,LeaseCommand l,JobEvent e){open();assertEquals(v.revision,e.expectedRevision);assertEquals(v.jobId,id);if(e.state.equals("completed"))completed++;return v=new JobView(id,v.spec,e.state,v.revision+1,v.desiredState,v.fence,A,e.reasonCode,e.resumePhase,null,S);}
  public JobView stopAck(String id,LeaseCommand l,String e,long r){throw new AssertionError("no cancel in scenario");}
  public void close(){closed=true;closeCount++;}
 }
 @Test public void emptyQueueBacksOffAndHeartbeatsUntilExplicitStop()throws Exception {Clock c=new Clock();Server api=new Server(c,0);try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);c.onSleep=()->{if(c.now>=31)s.requestStop();};s.run();assertEquals(6,api.claims.size());double[] expected={0,1,3,7,15,23};for(int i=0;i<expected.length;i++)assertEquals(expected[i],api.claims.get(i),.11);assertEquals(3,api.heartbeats.size());for(int i=0;i<3;i++)assertEquals((i+1)*10,api.heartbeats.get(i),.11);assertTrue(api.closed);}}
 @Test public void completedJobsContinueWithoutAnotherUserClick()throws Exception {Clock c=new Clock();Server api=new Server(c,2);try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);c.onSleep=()->{if(api.claims.size()>=3)s.requestStop();};s.run();assertEquals(2,api.completed);assertEquals(3,api.claims.size());assertTrue(api.closed);}}
 @Test public void ambiguousClaimNeverRetries()throws Exception {Clock c=new Clock();Server api=new Server(c,0);api.ambiguous=true;try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);s.run();assertEquals(1,api.claims.size());assertEquals("claim_unconfirmed",s.status());assertTrue(api.closed);}}
 @Test public void profileAttentionNeverClaimsAnotherJob()throws Exception {Clock c=new Clock();Server api=new Server(c,3);api.unknownProfile=true;try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);s.run();assertEquals(1,api.claims.size());assertEquals("needs_attention",s.status());assertEquals(0,api.completed);}}
 @Test public void unauthorizedHelloDisconnectsWithoutClaim()throws Exception {Clock c=new Clock();Server api=new Server(c,0);api.unauthorized=true;try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);s.run();assertTrue(api.claims.isEmpty());assertEquals(1,api.helloCount);assertTrue(api.closed);}}
 @Test public void stopBeforeRunNeverMakesNetworkRequest()throws Exception {Clock c=new Clock();Server api=new Server(c,0);try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);s.requestStop();s.run();assertEquals(0,api.helloCount);assertTrue(api.claims.isEmpty());assertTrue(api.closed);}}
 @Test public void heartbeatFailureDisconnectsRatherThanReconnecting()throws Exception {Clock c=new Clock();Server api=new Server(c,0);api.heartbeatFailure=true;try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);s.run();assertEquals(4,api.claims.size());assertEquals(1,api.heartbeats.size());assertEquals("connection_failed",s.status());assertTrue(api.closed);}}
 @Test public void leaseFailureDisconnectsRatherThanClaimingNextJob()throws Exception {Clock c=new Clock();Server api=new Server(c,3);api.renewFailure=true;try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);s.run();assertEquals(1,api.claims.size());assertEquals("needs_attention",s.status());assertTrue(api.closed);}}
 @Test public void leaveDuringExecutionPreservesUnconfirmedIntentWithoutNextClaim()throws Exception {Clock c=new Clock();Server api=new Server(c,3);try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);c.onSleep=s::requestStop;s.run();assertEquals(1,api.claims.size());assertEquals("running",s.currentJob().state);assertEquals("disconnected_unconfirmed",s.status());assertTrue(j.hasStart(s.currentJob().jobId));assertEquals(0,api.completed);}}
 @Test public void simultaneousStorageFailureAndLeaveRetainsVisibleHealthLatch()throws Exception {Clock c=new Clock();Server api=new Server(c,3);try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);c.onSleep=()->{try{java.lang.reflect.Field f=RemoteJournal.class.getDeclaredField("data");f.setAccessible(true);((java.nio.channels.FileChannel)f.get(j)).close();try{j.bind("99999999-9999-4999-8999-999999999999",S,8,"a".repeat(64));}catch(java.io.IOException expected){}}catch(Exception e){throw new AssertionError(e);}s.requestStop();};s.run();assertEquals(1,api.claims.size());assertEquals("storage_failed_not_persisted",s.status());assertEquals(0,api.completed);}}
 @Test public void explicitDisconnectInterruptsBlockedHello()throws Exception {
  Clock c=new Clock();java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicBoolean interrupted=new java.util.concurrent.atomic.AtomicBoolean();
  Server api=new Server(c,0){@Override public HelloResult hello(AgentHello h){entered.countDown();try{Thread.sleep(30000);}catch(InterruptedException e){interrupted.set(true);Thread.currentThread().interrupt();throw new ControlException("transport_failed",0,true,true);}throw new AssertionError("should be interrupted");}};
  try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);Thread worker=new Thread(s::run);worker.start();try{assertTrue(entered.await(1,java.util.concurrent.TimeUnit.SECONDS));s.requestStop();worker.join(500);assertFalse("disconnect must interrupt active request",worker.isAlive());assertTrue(interrupted.get());assertTrue(api.claims.isEmpty());}finally{worker.interrupt();worker.join(1000);}}
 }
 @Test public void explicitDisconnectInterruptsIdleSleep()throws Exception {
  java.util.concurrent.CountDownLatch sleeping=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicBoolean interrupted=new java.util.concurrent.atomic.AtomicBoolean();
  Clock serverClock=new Clock();Server api=new Server(serverClock,0);
  RemoteClock c=new RemoteClock(){public double monotonicSeconds(){return System.nanoTime()/1e9;}public Instant utcNow(){return Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);}public void sleepMillis(long ms)throws InterruptedException{sleeping.countDown();try{Thread.sleep(ms);}catch(InterruptedException e){interrupted.set(true);throw e;}}};
  try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);Thread worker=new Thread(s::run);worker.start();try{assertTrue(sleeping.await(1,java.util.concurrent.TimeUnit.SECONDS));s.requestStop();worker.join(500);assertFalse(worker.isAlive());assertTrue("owner thread sleep must receive interruption",interrupted.get());}finally{worker.interrupt();worker.join(1000);}}
 }
 @Test public void secondJobWithReusedFenceStopsBeforeItsStart()throws Exception {
  Clock c=new Clock();Server api=new Server(c,2){@Override public LeaseGrant claim(String device){LeaseGrant grant=super.claim(device);if(claims.size()==2){v=new JobView(v.jobId,v.spec,v.state,v.revision,v.desiredState,1,A,null,null,null,S);return new LeaseGrant(v,"test-lease",1,c.utcNow().plusSeconds(30));}return grant;}};
  try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);s.run();assertEquals(2,api.claims.size());assertEquals(1,api.completed);assertFalse(j.hasStart(api.v.jobId));assertNotEquals("completed",s.status());}
 }
 @Test public void explicitDisconnectInterruptsBlockedClaimAndNeverRetries()throws Exception {
  Clock c=new Clock();java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1);
  Server api=new Server(c,0){@Override public LeaseGrant claim(String device){claims.add(c.now);entered.countDown();try{Thread.sleep(30000);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new ControlException("transport_failed",0,true,true);}throw new AssertionError("must interrupt");}};
  try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);Thread worker=new Thread(s::run);worker.start();try{assertTrue(entered.await(1,java.util.concurrent.TimeUnit.SECONDS));s.requestStop();worker.join(500);assertFalse(worker.isAlive());assertEquals(1,api.claims.size());assertEquals("disconnected_unconfirmed",s.status());assertEquals(1,api.closeCount);}finally{worker.interrupt();worker.join(1000);}}
 }
 @Test public void repeatedStopAfterRunDoesNotInterruptReusedWorkerAndClosesOnce()throws Exception {
  Clock c=new Clock();Server api=new Server(c,0);api.unauthorized=true;
  java.util.concurrent.CountDownLatch ended=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicBoolean interrupted=new java.util.concurrent.atomic.AtomicBoolean();
  try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("session"))){RemoteForegroundSession s=new RemoteForegroundSession(api,j,c,A,D,2);Thread worker=new Thread(()->{s.run();ended.countDown();try{release.await();}catch(InterruptedException e){interrupted.set(true);}});worker.start();try{assertTrue(ended.await(1,java.util.concurrent.TimeUnit.SECONDS));s.requestStop();s.requestStop();release.countDown();worker.join(500);assertFalse(worker.isAlive());assertFalse(interrupted.get());assertEquals(1,api.closeCount);}finally{release.countDown();worker.interrupt();worker.join(1000);}}
 }

}
